#define _POSIX_C_SOURCE 200809L

#include "store/ring.h"

#include <errno.h>
#include <fcntl.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "log.h"
#include "store/crc32.h"

#define RING_FILE_SIZE ((off_t)RING_SLOTS * RING_REC_SIZE)
#define CRC_SPAN 12u

struct ring {
	int fd;
	char *name;		/* basename, for log lines */
	uint32_t next_slot;
	uint32_t next_seq;
};

enum slot_state { SLOT_FREE, SLOT_VALID, SLOT_BAD };

struct scan {
	size_t n_valid;
	size_t n_bad;
	int found;
	uint32_t max_seq;
	uint32_t max_slot;
};

static void put_le32(unsigned char *p, uint32_t v)
{
	p[0] = (unsigned char)v;
	p[1] = (unsigned char)(v >> 8);
	p[2] = (unsigned char)(v >> 16);
	p[3] = (unsigned char)(v >> 24);
}

static uint32_t get_le32(const unsigned char *p)
{
	return (uint32_t)p[0] | (uint32_t)p[1] << 8 |
	       (uint32_t)p[2] << 16 | (uint32_t)p[3] << 24;
}

static void encode(const struct ring_record *rec, unsigned char *out)
{
	put_le32(out, rec->seq);
	put_le32(out + 4, rec->ts);
	out[8] = (unsigned char)rec->reading;
	out[9] = (unsigned char)(rec->reading >> 8);
	out[10] = rec->fault;
	out[11] = 0;
	put_le32(out + 12, crc32(out, CRC_SPAN));
}

static enum slot_state decode(const unsigned char *in, struct ring_record *rec)
{
	unsigned i;

	for (i = 0; i < RING_REC_SIZE && in[i] == 0; i++)
		;
	if (i == RING_REC_SIZE)
		return SLOT_FREE;
	if (crc32(in, CRC_SPAN) != get_le32(in + 12))
		return SLOT_BAD;
	rec->seq = get_le32(in);
	rec->ts = get_le32(in + 4);
	rec->reading = (uint16_t)(in[8] | in[9] << 8);
	rec->fault = in[10];
	return SLOT_VALID;
}

static const char *base_name(const char *path)
{
	const char *slash = strrchr(path, '/');

	return slash ? slash + 1 : path;
}

/*
 * Decode nslots records from buf. Valid records go to out (if non-NULL) in
 * slot order. Sequence numbers are not expected to wrap (2^32 records at
 * one per 20 min is ~160,000 years).
 */
static void scan_slots(const unsigned char *buf, uint32_t nslots,
		       const char *name, struct ring_record *out,
		       struct scan *s)
{
	struct ring_record rec;

	memset(s, 0, sizeof *s);
	for (uint32_t slot = 0; slot < nslots; slot++) {
		switch (decode(buf + (size_t)slot * RING_REC_SIZE, &rec)) {
		case SLOT_FREE:
			break;
		case SLOT_BAD:
			log_msg(L_INFO, "store", "%s slot %u bad CRC, discarded",
				name, (unsigned)slot);
			s->n_bad++;
			break;
		case SLOT_VALID:
			if (out)
				out[s->n_valid] = rec;
			s->n_valid++;
			if (!s->found || rec.seq > s->max_seq) {
				s->found = 1;
				s->max_seq = rec.seq;
				s->max_slot = slot;
			}
			break;
		}
	}
}

static int read_full(int fd, unsigned char *buf, size_t len, const char *name)
{
	size_t done = 0;

	while (done < len) {
		ssize_t n = pread(fd, buf + done, len - done, (off_t)done);

		if (n < 0) {
			if (errno == EINTR)
				continue;
			log_msg(L_ERROR, "store", "%s read failed (errno=%d)",
				name, errno);
			return -1;
		}
		if (n == 0) {
			log_msg(L_ERROR, "store", "%s unexpected EOF at byte %zu",
				name, done);
			return -1;
		}
		done += (size_t)n;
	}
	return 0;
}

/* fsync the directory holding path, so a newly created file survives. */
static int fsync_dir(const char *path, const char *name)
{
	char *dir = NULL;
	char *slash;
	const char *d;
	int fd = -1;
	int ret = -1;

	dir = strdup(path);
	if (!dir) {
		log_msg(L_ERROR, "store", "%s out of memory", name);
		goto out;
	}
	slash = strrchr(dir, '/');
	if (!slash) {
		d = ".";
	} else {
		if (slash == dir)
			slash[1] = '\0';
		else
			*slash = '\0';
		d = dir;
	}
	fd = open(d, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
	if (fd < 0) {
		log_msg(L_ERROR, "store", "%s open dir %s failed (errno=%d)",
			name, d, errno);
		goto out;
	}
	if (fsync(fd) < 0) {
		log_msg(L_ERROR, "store", "%s fsync dir %s failed (errno=%d)",
			name, d, errno);
		goto out;
	}
	ret = 0;
out:
	if (fd >= 0 && close(fd) < 0) {
		log_msg(L_ERROR, "store", "%s close dir failed (errno=%d)",
			name, errno);
		ret = -1;
	}
	free(dir);
	return ret;
}

int ring_open(const char *path, struct ring **out)
{
	const char *name = base_name(path);
	struct ring *r = NULL;
	unsigned char *buf = NULL;
	struct stat st;
	struct scan s;
	int fd = -1;
	int ret = -1;

	*out = NULL;
	r = calloc(1, sizeof *r);
	if (!r) {
		log_msg(L_ERROR, "store", "%s out of memory", name);
		goto out;
	}
	r->fd = -1;
	r->name = strdup(name);
	if (!r->name) {
		log_msg(L_ERROR, "store", "%s out of memory", name);
		goto out;
	}

	fd = open(path, O_RDWR | O_CREAT | O_CLOEXEC, 0644);
	if (fd < 0) {
		log_msg(L_ERROR, "store", "%s open %s failed (errno=%d)",
			name, path, errno);
		goto out;
	}
	if (fstat(fd, &st) < 0) {
		log_msg(L_ERROR, "store", "%s fstat failed (errno=%d)",
			name, errno);
		goto out;
	}
	if (st.st_size > RING_FILE_SIZE) {
		log_msg(L_ERROR, "store",
			"%s is %lld bytes, larger than a ring (%lld), refusing",
			name, (long long)st.st_size, (long long)RING_FILE_SIZE);
		goto out;
	}
	if (st.st_size < RING_FILE_SIZE) {
		if (st.st_size != 0)
			log_msg(L_WARN, "store", "%s short (%lld bytes), extending",
				name, (long long)st.st_size);
		if (ftruncate(fd, RING_FILE_SIZE) < 0) {
			log_msg(L_ERROR, "store", "%s ftruncate failed (errno=%d)",
				name, errno);
			goto out;
		}
		if (fsync(fd) < 0) {
			log_msg(L_ERROR, "store", "%s fsync failed (errno=%d)",
				name, errno);
			goto out;
		}
		if (fsync_dir(path, name) < 0)
			goto out;
	}

	buf = malloc((size_t)RING_FILE_SIZE);
	if (!buf) {
		log_msg(L_ERROR, "store", "%s out of memory", name);
		goto out;
	}
	if (read_full(fd, buf, (size_t)RING_FILE_SIZE, name) < 0)
		goto out;

	scan_slots(buf, RING_SLOTS, name, NULL, &s);
	r->fd = fd;
	fd = -1;
	r->next_slot = s.found ? (s.max_slot + 1) % RING_SLOTS : 0;
	r->next_seq = s.found ? s.max_seq + 1 : 1;
	log_msg(L_INFO, "store", "%s opened: %zu valid, %zu bad, next slot %u seq %u",
		name, s.n_valid, s.n_bad, (unsigned)r->next_slot,
		(unsigned)r->next_seq);
	*out = r;
	r = NULL;
	ret = 0;
out:
	free(buf);
	if (fd >= 0 && close(fd) < 0)
		log_msg(L_ERROR, "store", "%s close failed (errno=%d)",
			name, errno);
	if (r) {
		free(r->name);
		free(r);
	}
	return ret;
}

int ring_append(struct ring *r, uint32_t ts, uint16_t reading, uint8_t fault)
{
	struct ring_record rec = {
		.seq = r->next_seq, .ts = ts, .reading = reading, .fault = fault,
	};
	unsigned char buf[RING_REC_SIZE];
	off_t off = (off_t)r->next_slot * RING_REC_SIZE;
	size_t done = 0;

	encode(&rec, buf);
	while (done < sizeof buf) {
		ssize_t n = pwrite(r->fd, buf + done, sizeof buf - done,
				   off + (off_t)done);

		if (n < 0) {
			if (errno == EINTR)
				continue;
			log_msg(L_ERROR, "store", "%s write slot %u failed (errno=%d)",
				r->name, (unsigned)r->next_slot, errno);
			return -1;
		}
		if (n == 0) {
			log_msg(L_ERROR, "store", "%s write slot %u wrote 0 bytes",
				r->name, (unsigned)r->next_slot);
			return -1;
		}
		done += (size_t)n;
	}
	if (fsync(r->fd) < 0) {
		log_msg(L_ERROR, "store", "%s fsync failed (errno=%d)",
			r->name, errno);
		return -1;
	}
	/* Only advance once durable; a failed write retries the same slot. */
	r->next_slot = (r->next_slot + 1) % RING_SLOTS;
	r->next_seq++;
	return 0;
}

int ring_close(struct ring *r)
{
	int ret = 0;

	if (!r)
		return 0;
	if (r->fd >= 0 && close(r->fd) < 0) {
		log_msg(L_ERROR, "store", "%s close failed (errno=%d)",
			r->name, errno);
		ret = -1;
	}
	free(r->name);
	free(r);
	return ret;
}

int ring_read_all(const char *path, struct ring_record *out,
		  size_t *n_valid, size_t *n_bad)
{
	const char *name = base_name(path);
	unsigned char *buf = NULL;
	struct stat st;
	struct scan s;
	uint32_t nslots;
	int fd = -1;
	int ret = -1;

	fd = open(path, O_RDONLY | O_CLOEXEC);
	if (fd < 0) {
		log_msg(L_ERROR, "store", "%s open %s failed (errno=%d)",
			name, path, errno);
		goto out;
	}
	if (fstat(fd, &st) < 0) {
		log_msg(L_ERROR, "store", "%s fstat failed (errno=%d)",
			name, errno);
		goto out;
	}
	if (st.st_size > RING_FILE_SIZE) {
		log_msg(L_ERROR, "store",
			"%s is %lld bytes, larger than a ring (%lld)",
			name, (long long)st.st_size, (long long)RING_FILE_SIZE);
		goto out;
	}
	if (st.st_size < RING_FILE_SIZE)
		log_msg(L_WARN, "store", "%s short (%lld bytes), reading whole slots only",
			name, (long long)st.st_size);
	nslots = (uint32_t)(st.st_size / RING_REC_SIZE);

	buf = malloc((size_t)RING_FILE_SIZE);
	if (!buf) {
		log_msg(L_ERROR, "store", "%s out of memory", name);
		goto out;
	}
	if (read_full(fd, buf, (size_t)nslots * RING_REC_SIZE, name) < 0)
		goto out;

	scan_slots(buf, nslots, name, out, &s);
	*n_valid = s.n_valid;
	*n_bad = s.n_bad;
	ret = 0;
out:
	free(buf);
	if (fd >= 0 && close(fd) < 0) {
		log_msg(L_ERROR, "store", "%s close failed (errno=%d)",
			name, errno);
		ret = -1;
	}
	return ret;
}

/*
 * Light monitor: reads lux from a BH1750 on /dev/i2c-1 every interval and
 * stores each reading in the light ring file.
 *
 * Exit codes: 0 on SIGTERM/SIGINT, 1 on fatal error, 2 on bad usage.
 */
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <sys/signalfd.h>
#include <sys/timerfd.h>
#include <time.h>
#include <unistd.h>

#include <linux/i2c-dev.h>

#include "log.h"
#include "store/ring.h"

#define I2C_DEV			"/dev/i2c-1"
#define BH1750_ADDR		0x23
#define BH1750_POWER_ON		0x01
#define BH1750_ONE_TIME_HRES	0x20	/* measure once, then power down */
#define BH1750_MEAS_MS		180	/* max high-res measurement time */
#define READ_ATTEMPTS		3
#define RETRY_MS		100
#define DEFAULT_INTERVAL_S	1200
#define HEARTBEAT_S		3600
#define DEFAULT_RING		"data/light.ring"

struct stats {
	unsigned long readings;
	unsigned long faults;
	unsigned long store_errors;
};

static void usage(FILE *f, const char *prog)
{
	fprintf(f, "usage: %s [-i seconds] [-f ringfile]\n"
		"  -i  read interval, 1..%d seconds (default %d)\n"
		"  -f  ring file (default %s)\n",
		prog, DEFAULT_INTERVAL_S, DEFAULT_INTERVAL_S, DEFAULT_RING);
}

static int parse_interval(const char *s, long *out)
{
	char *end;
	long v;

	errno = 0;
	v = strtol(s, &end, 10);
	if (errno || end == s || *end != '\0' || v < 1 || v > DEFAULT_INTERVAL_S)
		return -1;
	*out = v;
	return 0;
}

static void close_fd(int *fd, const char *what)
{
	if (*fd >= 0 && close(*fd) < 0)
		log_msg(L_WARN, "light", "close %s failed (errno=%d)", what, errno);
	*fd = -1;
}

static void sleep_ms(long ms)
{
	struct timespec ts = { .tv_sec = ms / 1000, .tv_nsec = (ms % 1000) * 1000000L };

	while (nanosleep(&ts, &ts) < 0) {
		if (errno != EINTR) {
			log_msg(L_WARN, "light", "nanosleep failed (errno=%d)", errno);
			return;
		}
	}
}

static uint32_t now_unix(void)
{
	struct timespec ts;

	if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
		log_msg(L_ERROR, "light", "clock_gettime failed (errno=%d)", errno);
		return 0;
	}
	if (ts.tv_sec < 0 || (uint64_t)ts.tv_sec > UINT32_MAX) {
		log_msg(L_WARN, "light", "clock out of range (%lld)",
			(long long)ts.tv_sec);
		return 0;
	}
	return (uint32_t)ts.tv_sec;
}

static int bus_open(void)
{
	int fd = open(I2C_DEV, O_RDWR | O_CLOEXEC);
	int err;

	if (fd < 0) {
		log_msg(L_WARN, "light", "open %s failed (errno=%d)", I2C_DEV, errno);
		return -1;
	}
	if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
		err = errno;
		log_msg(L_WARN, "light", "ioctl I2C_SLAVE 0x%02x failed (errno=%d)",
			BH1750_ADDR, err);
		close_fd(&fd, I2C_DEV);
		errno = err;
		return -1;
	}
	return fd;
}

static int bh1750_cmd(int fd, uint8_t cmd)
{
	ssize_t n = write(fd, &cmd, 1);

	if (n == 1)
		return 0;
	if (n >= 0)
		errno = EIO;
	log_msg(L_WARN, "light", "i2c write 0x%02x failed (errno=%d)", cmd, errno);
	return -1;
}

static int bh1750_measure(int fd, uint16_t *lux)
{
	uint8_t buf[2];
	uint32_t raw;
	ssize_t n;

	if (bh1750_cmd(fd, BH1750_POWER_ON) < 0 ||
	    bh1750_cmd(fd, BH1750_ONE_TIME_HRES) < 0)
		return -1;
	sleep_ms(BH1750_MEAS_MS);
	n = read(fd, buf, sizeof buf);
	if (n != (ssize_t)sizeof buf) {
		if (n >= 0)
			errno = EIO;
		log_msg(L_WARN, "light", "i2c read failed (errno=%d)", errno);
		return -1;
	}
	raw = (uint32_t)buf[0] << 8 | buf[1];
	*lux = (uint16_t)((raw * 5 + 3) / 6);	/* lux = raw / 1.2, rounded */
	return 0;
}

/* Try up to READ_ATTEMPTS times, reopening the bus after any failure. */
static int read_light(int *bus, uint16_t *lux)
{
	int err = 0;

	for (int attempt = 1; attempt <= READ_ATTEMPTS; attempt++) {
		if (attempt > 1)
			sleep_ms(RETRY_MS);
		if (*bus < 0)
			*bus = bus_open();
		if (*bus >= 0 && bh1750_measure(*bus, lux) == 0)
			return 0;
		err = errno;
		close_fd(bus, I2C_DEV);
	}
	log_msg(L_WARN, "light", "i2c read failed x%d (errno=%d), skipped",
		READ_ATTEMPTS, err);
	return -1;
}

static void take_reading(struct ring *ring, int *bus, struct stats *st)
{
	uint32_t ts = now_unix();
	uint16_t lux = 0;
	uint8_t fault = 0;

	if (read_light(bus, &lux) < 0) {
		lux = 0;
		fault = 1;
		st->faults++;
	}
	st->readings++;
	if (ring_append(ring, ts, lux, fault) < 0) {
		st->store_errors++;
		log_msg(L_WARN, "light", "reading not stored (lux=%u fault=%u)",
			(unsigned)lux, (unsigned)fault);
		return;
	}
	log_msg(L_INFO, "light", "lux=%u fault=%u", (unsigned)lux, (unsigned)fault);
}

static int make_timer(long secs, const char *what)
{
	struct itimerspec its = {
		.it_interval = { .tv_sec = secs },
		.it_value = { .tv_sec = secs },
	};
	int fd = timerfd_create(CLOCK_MONOTONIC, TFD_CLOEXEC);

	if (fd < 0) {
		log_msg(L_ERROR, "light", "timerfd_create %s failed (errno=%d)",
			what, errno);
		return -1;
	}
	if (timerfd_settime(fd, 0, &its, NULL) < 0) {
		log_msg(L_ERROR, "light", "timerfd_settime %s failed (errno=%d)",
			what, errno);
		close_fd(&fd, what);
		return -1;
	}
	return fd;
}

static int read_timer(int fd, const char *what, uint64_t *expirations)
{
	ssize_t n;

	do
		n = read(fd, expirations, sizeof *expirations);
	while (n < 0 && errno == EINTR);
	if (n != (ssize_t)sizeof *expirations) {
		log_msg(L_ERROR, "light", "read %s timer failed (n=%zd errno=%d)",
			what, n, n < 0 ? errno : 0);
		return -1;
	}
	return 0;
}

int main(int argc, char **argv)
{
	const char *path = DEFAULT_RING;
	long interval = DEFAULT_INTERVAL_S;
	struct ring *ring = NULL;
	struct stats st = { 0 };
	int bus = -1, sig_fd = -1, tick_fd = -1, hb_fd = -1;
	int ret = 1;
	sigset_t mask;
	int opt;

	while ((opt = getopt(argc, argv, "i:f:h")) != -1) {
		switch (opt) {
		case 'i':
			if (parse_interval(optarg, &interval) < 0) {
				fprintf(stderr, "%s: bad interval '%s'\n", argv[0], optarg);
				usage(stderr, argv[0]);
				return 2;
			}
			break;
		case 'f':
			path = optarg;
			break;
		case 'h':
			usage(stdout, argv[0]);
			return 0;
		default:
			usage(stderr, argv[0]);
			return 2;
		}
	}
	if (optind != argc) {
		usage(stderr, argv[0]);
		return 2;
	}

	/* Take SIGTERM/SIGINT through a signalfd so shutdown can't race poll(). */
	if (sigemptyset(&mask) < 0 || sigaddset(&mask, SIGTERM) < 0 ||
	    sigaddset(&mask, SIGINT) < 0) {
		log_msg(L_ERROR, "light", "sigset setup failed (errno=%d)", errno);
		goto out;
	}
	if (sigprocmask(SIG_BLOCK, &mask, NULL) < 0) {
		log_msg(L_ERROR, "light", "sigprocmask failed (errno=%d)", errno);
		goto out;
	}
	sig_fd = signalfd(-1, &mask, SFD_CLOEXEC);
	if (sig_fd < 0) {
		log_msg(L_ERROR, "light", "signalfd failed (errno=%d)", errno);
		goto out;
	}

	if (ring_open(path, &ring) < 0)
		goto out;
	tick_fd = make_timer(interval, "read");
	if (tick_fd < 0)
		goto out;
	hb_fd = make_timer(HEARTBEAT_S, "heartbeat");
	if (hb_fd < 0)
		goto out;

	log_msg(L_INFO, "light", "heartbeat: started, interval %lds, ring %s",
		interval, path);
	take_reading(ring, &bus, &st);

	for (;;) {
		struct pollfd pfd[3] = {
			{ .fd = sig_fd, .events = POLLIN },
			{ .fd = tick_fd, .events = POLLIN },
			{ .fd = hb_fd, .events = POLLIN },
		};
		uint64_t exp;

		if (poll(pfd, 3, -1) < 0) {
			if (errno == EINTR)
				continue;
			log_msg(L_ERROR, "light", "poll failed (errno=%d)", errno);
			goto out;
		}
		for (int i = 0; i < 3; i++) {
			if (pfd[i].revents & (POLLERR | POLLHUP | POLLNVAL)) {
				log_msg(L_ERROR, "light", "poll fd %d revents 0x%x",
					pfd[i].fd, (unsigned)pfd[i].revents);
				goto out;
			}
		}
		if (pfd[0].revents & POLLIN) {
			struct signalfd_siginfo si;
			ssize_t n = read(sig_fd, &si, sizeof si);

			if (n != (ssize_t)sizeof si) {
				log_msg(L_ERROR, "light", "signalfd read failed (n=%zd errno=%d)",
					n, n < 0 ? errno : 0);
				goto out;
			}
			log_msg(L_INFO, "light", "signal %u, exiting",
				(unsigned)si.ssi_signo);
			ret = 0;
			goto out;
		}
		if (pfd[1].revents & POLLIN) {
			if (read_timer(tick_fd, "read", &exp) < 0)
				goto out;
			if (exp > 1)
				log_msg(L_WARN, "light", "missed %llu read ticks",
					(unsigned long long)(exp - 1));
			take_reading(ring, &bus, &st);
		}
		if (pfd[2].revents & POLLIN) {
			if (read_timer(hb_fd, "heartbeat", &exp) < 0)
				goto out;
			log_msg(L_INFO, "light",
				"heartbeat: readings=%lu faults=%lu store_errors=%lu",
				st.readings, st.faults, st.store_errors);
		}
	}

out:
	close_fd(&hb_fd, "heartbeat timer");
	close_fd(&tick_fd, "read timer");
	close_fd(&bus, I2C_DEV);
	close_fd(&sig_fd, "signalfd");
	if (ring_close(ring) < 0)
		ret = 1;
	log_msg(L_INFO, "light", "exit %d", ret);
	return ret;
}

/* ringdump: print every valid record in a ring file, oldest first. */
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#include "log.h"
#include "store/ring.h"

static int by_seq(const void *a, const void *b)
{
	const struct ring_record *x = a, *y = b;

	return (x->seq > y->seq) - (x->seq < y->seq);
}

int main(int argc, char **argv)
{
	struct ring_record *recs = NULL;
	size_t n_valid = 0, n_bad = 0;
	int ret = 1;

	if (argc != 2) {
		fprintf(stderr, "usage: %s RINGFILE\n", argv[0]);
		return 2;
	}
	recs = calloc(RING_SLOTS, sizeof *recs);
	if (!recs) {
		log_msg(L_ERROR, "ringdump", "out of memory");
		goto out;
	}
	if (ring_read_all(argv[1], recs, &n_valid, &n_bad) < 0)
		goto out;
	qsort(recs, n_valid, sizeof *recs, by_seq);

	printf("%10s  %-19s  %7s  %s\n", "seq", "time", "reading", "fault");
	for (size_t i = 0; i < n_valid; i++) {
		time_t t = (time_t)recs[i].ts;
		struct tm tm;
		char when[32];

		if (!localtime_r(&t, &tm) ||
		    strftime(when, sizeof when, "%Y-%m-%d %H:%M:%S", &tm) == 0)
			snprintf(when, sizeof when, "@%" PRIu32, recs[i].ts);
		printf("%10" PRIu32 "  %-19s  %7u  %u\n", recs[i].seq, when,
		       (unsigned)recs[i].reading, (unsigned)recs[i].fault);
	}
	if (fflush(stdout) == EOF || ferror(stdout)) {
		log_msg(L_ERROR, "ringdump", "write to stdout failed (errno=%d)", errno);
		goto out;
	}
	fprintf(stderr, "ringdump: %zu valid, %zu bad slots\n", n_valid, n_bad);
	ret = 0;
out:
	free(recs);
	return ret;
}

